// Command opencode-rig runs ONE opencode session the way the clankerbar fleet
// does, with every outside dependency replaced:
//
//   - the session config is generated by the CLI's own harness.OpencodeSessionConfig,
//     so the permission policy, the MCP servers out of Code Mode and the agent
//     pins are the fleet's;
//   - the clankerbar MCP server is a local stub serving the plane's REAL tool
//     schemas (fetched read-only from the plane, or loaded from a file) and
//     returning canned responses, so nothing is ever written to the backlog;
//   - the provider's baseURL points at an in-process logging pass-through that
//     records each request body (never the Authorization header) and forwards
//     it to the real provider, so the exact wire format is on disk;
//   - XDG data/state/cache are isolated, so the fleet's sessions and database
//     are untouched.
//
// Run it with scripts/opencode-rig/run.sh. See scripts/opencode-rig/README.md
// for the scenarios, the traps this rig guards against, and the cost: every run
// makes real provider requests.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func main() {
	if len(os.Args) < 2 {
		usage(os.Stderr)
		os.Exit(2)
	}
	switch os.Args[1] {
	case "run":
		os.Exit(runCmd(os.Args[2:]))
	case "stub":
		// Internal: the stdio MCP server opencode spawns. Exposed so a failing
		// rig can be reproduced by hand, and so the smoke test drives the same
		// entry point.
		os.Exit(stubCmd(os.Args[2:]))
	case "session-config":
		// The tiny "go run" entry point: print the document the adapter would
		// pin as OPENCODE_CONFIG_CONTENT, from the CLI's own code.
		os.Exit(sessionConfigCmd(os.Args[2:]))
	case "fetch-schemas":
		os.Exit(fetchSchemasCmd(os.Args[2:]))
	case "help", "-h", "--help":
		usage(os.Stdout)
	default:
		fmt.Fprintf(os.Stderr, "opencode-rig: unknown subcommand %q\n\n", os.Args[1])
		usage(os.Stderr)
		os.Exit(2)
	}
}

func usage(w *os.File) {
	fmt.Fprint(w, `opencode-rig - one fleet-shaped opencode session, offline from the backlog

Usage:
  scripts/opencode-rig/run.sh [run] [flags]     run one session
  scripts/opencode-rig/run.sh session-config    print the generated OPENCODE_CONFIG_CONTENT
  scripts/opencode-rig/run.sh fetch-schemas     fetch the plane's tools/list to a file

Run flags (run):
  --scenario padding|reasoning-replay|schema   experiment to run (default padding)
  --model provider/model                       REQUIRED; the fleet model, e.g.
                                               commandcode/deepseek/deepseek-v4.1-flash
  --provider id                                override the provider id parsed from --model
  --upstream URL                               real provider base URL (default: the
                                               provider's options.baseURL in the config)
  --mcp-config file                            source config (default
                                               ~/.config/clankerbar/opencode-mcp.json,
                                               else a minimal config)
  --config-dir dir                             OPENCODE_CONFIG_DIR to pass through
  --workdir dir                                session sandbox (default <out>/sandbox)
  --schemas live|file                          tool catalog: fetch the plane's real
                                               tools/list, or load a file
  --plane-url URL                              plane MCP URL for the live fetch
  --schema-tool name                           tool the schema scenario calls
  --plane-key-file file                        read CLANKERBAR_API_KEY from this file
  --provider-key-file file                     read COMMANDCODE_API_KEY from this file
  --out dir                                    run directory (default
                                               $TMPDIR/opencode-rig/<scenario>-<stamp>)
  --deadline duration                          kill the session after this (default 5m)
  --max-tool-calls N                           stop after N stub calls (default 6)
  --prompt text                                override the scenario prompt
  --opencode-bin path                          opencode binary (default "opencode")
  --dry-run                                    resolve and print everything, spawn nothing
  --keep                                       accepted for symmetry; runs are always kept
`)
}

// flagSet returns the one flag style every subcommand uses: ContinueOnError so
// the caller owns the exit code, and errors on stderr where a script expects
// them.
func flagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	return fs
}

// expandHome expands a leading "~" so a flag can name a config path the way
// the fleet's config files do.
func expandHome(path string) string {
	if path == "~" || strings.HasPrefix(path, "~/") {
		if home, err := os.UserHomeDir(); err == nil {
			return filepath.Join(home, strings.TrimPrefix(strings.TrimPrefix(path, "~"), "/"))
		}
	}
	return path
}

// parseFlags keeps flag parsing (and its exit codes) in one place.
func parseFlags(fs *flag.FlagSet, args []string) error {
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return err
	}
	if fs.NArg() > 0 {
		return fmt.Errorf("unexpected argument %q", fs.Arg(0))
	}
	return nil
}

// runID is the human handle for one rig run: the scenario plus a UTC stamp.
// It is also printed in the report and used as the directory name, so a log
// line or a directory can always be tied back to the run that made it.
func runID(scenario string, at time.Time) string {
	return scenario + "-" + at.UTC().Format("20060102T150405Z")
}
